export function listScenarios() {
    const out = [];
    for (const name of DEMO_SCENARIOS) {
        const def = loadDefinition(name);
        out.push({ name: name, description: def.description, expect: def.expect });
    }
    return { scenarios: out };
}
export function loadDefinition(scenario) {
    if (DEMO_SCENARIOS.indexOf(scenario) < 0) {
        throw new Error('DEMO-SCENARIO-UNKNOWN: ' + scenario + '（可选：' + DEMO_SCENARIOS.join(' / ') + '）');
    }
    const p = join(DEFINITIONS_DIR, scenario + '.json');
    if (!existsSync(p)) {
        throw new Error('DEMO-DEFINITION-MISSING: ' + p);
    }
    const def = JSON.parse(readFileSync(p, 'utf8'));
    if (def.scenario !== scenario) {
        throw new Error('DEMO-DEFINITION-MISMATCH: 文件 ' + scenario + '.json 内 scenario=' + def.scenario);
    }
    return def;
}
// #53/D-060④：demo 链本体已提炼至 audit/macro-b.ts（probeMacroBRepo/collectMacroB/evaluateMacroB），
// 本文件只留 fixture 生成 + 场景装配（披露块/裁决条目/报告输入的 scenario 语义面）。
function pickExcerpt(absOrRelPath, tokens, base) {
    const text = readFileSync(base ? join(base, absOrRelPath) : absOrRelPath, 'utf8');
    const lines = text.split(NL);
    if (tokens === null) {
        return { line: 1, text: lines[0].trim() };
    }
    for (let i = 0; i < lines.length; i++) {
        let all = true;
        for (const tk of tokens) {
            if (lines[i].indexOf(tk) < 0) {
                all = false;
            }
        }
        if (all) {
            return { line: i + 1, text: lines[i].trim() };
        }
    }
    throw new Error('EXCERPT-MISS: ' + absOrRelPath + ' tokens=' + String(tokens));
}
